_BUNDLED_MODULES['baked_assets'] = '# -*- coding: utf-8 -*-\n"""Shared source-derived resource layer.\n\nThe browser and Python runtime use the same canonical DATA/baked_assets.js\nresource. Python reads the JSON object assigned by that JavaScript file; it\ndoes not maintain a second baked_assets.json copy.\n"""\nfrom pathlib import Path\nimport json\nimport re\nimport pygame\n_HERE=Path(__file__).resolve()\nROOT=_HERE.parent if (_HERE.parent/\'DATA\').exists() else _HERE.parents[1]\nDATA=ROOT/\'DATA\'/\'baked_assets.js\'; _CACHE={}\ndef _data():\n    if \'manifest\' not in _CACHE:\n        text=DATA.read_text(encoding=\'utf-8\')\n        m=re.search(r\'window\\.MARIO_BAKED_DATA\\s*=\\s*(\\{.*\\});\\s*$\', text, re.S)\n        if not m: raise ValueError(f\'Invalid shared baked resource: {DATA}\')\n        _CACHE[\'manifest\']=json.loads(m.group(1))\n    return _CACHE[\'manifest\']\ndef p256_palette_vga(): return [list(x) for x in _data()[\'palettes\'][\'MPAL256\']]\ndef default_palette_vga(): return [list(x) for x in _data()[\'palettes\'][\'DEFAULT.PAL\']]\ndef _entry(name):\n    m=_data()[\'sprites\'].get(name) or _data()[\'pas_images\'].get(name)\n    if m is None: raise KeyError(name)\n    return m\ndef _source_image(name):\n    ent=_entry(name); key=ent[\'source_data\']; return _data()[\'source_images\'][key]\ndef _pixel_index(name,x,y):\n    src=_source_image(name); return src[\'pixels\'][int(y)*int(src[\'w\'])+int(x)]\ndef _pixel_alpha(name,x,y):\n    src=_source_image(name); a=src.get(\'alpha\')\n    if a is None: return 255\n    return a[int(y)*int(src[\'w\'])+int(x)]\ndef indexed_surface(name,scale=1,palette_vga=None,alpha=True):\n    ent=_entry(name); src=_source_image(name)\n    key=(name,int(scale),tuple(tuple(x) for x in palette_vga) if palette_vga is not None else None,alpha)\n    if palette_vga is None and key in _CACHE: return _CACHE[key].copy()\n    w,h=int(src[\'w\']),int(src[\'h\']); pal=palette_vga if palette_vga is not None else p256_palette_vga()\n    out=pygame.Surface((w,h),pygame.SRCALPHA)\n    for y in range(h):\n        for x in range(w):\n            idx=int(src[\'pixels\'][y*w+x]); a=int(src.get(\'alpha\',[255]*(w*h))[y*w+x])\n            if idx==0 or (alpha and a==0): continue\n            rgb=pal[idx]; out.set_at((x,y),(*[round(int(v)*255/63) for v in rgb],a))\n    if scale!=1: out=pygame.transform.scale(out,(w*scale,h*scale))\n    if palette_vga is None: _CACHE[key]=out.copy()\n    return out\ndef source_pixels(name): return list(_source_image(name)[\'pixels\'])\ndef pas_pixels(name): return source_pixels(name)\ndef background_map(name):\n    ent=_data()[\'backgrounds\'][name]; src=_data()[\'background_images\'][ent[\'source_data\']]\n    return tuple(int(v) for v in src[\'pixels\'])\ndef fonts(): return _data()[\'fonts\']\ndef demo_macro_bytes():\n    import struct; return struct.pack(\'<900H\',*[int(x)&0xffff for x in _data()[\'demo_macro\']])\ndef worlds_raw(): return _data()[\'worlds_raw\']\n'
_BUNDLED_MODULES['audio_runtime'] = '# -*- coding: utf-8 -*-\n"""Source-derived MP3 audio presentation.\n\nMUSIC.PAS is converted OFFLINE into complete MP3 tracks.  Runtime does not\ninterpret MUSIC.PAS note strings or synthesize a melody.  It only plays the\nalready-rendered MP3 selected by the source event.\n\nEvidence used for the conversion is kept in DATA/music_pas_mp3_v10.json:\nMUSIC.PAS note indices, AI-note frequency table, duration bytes, and the\n~70 Hz VGA retrace cadence.  The rendered waveform is a 50% duty PC-speaker\nsquare wave, then encoded as mono MP3.\n"""\nfrom pathlib import Path\n\n\nclass SourceAudio:\n    """Play pre-rendered source-derived MP3 assets.\n\n    BUFFERS.PAS gives a single PC-speaker path: SFX and music therefore share\n    one mixer channel.  MUSIC.PAS itself has already been converted into the\n    nine complete MP3 tracks in AUDIO/; no MUSIC.PAS playback state machine is\n    run by the Python game.\n    """\n    MUSIC_NAMES = {\n        "LifeMusic", "GrowMusic", "CoinMusic", "PipeMusic", "FireMusic",\n        "HitMusic", "DeadMusic", "NoteMusic", "StarMusic",\n    }\n\n    class _MusicCompat:\n        """Compatibility view for source code that reads music.beeper_sound.\n\n        MUSIC.PAS is NOT interpreted at runtime. This field only mirrors the\n        DOS sound-enable flag used by the translated game/config paths.\n        """\n        def __init__(self, owner):\n            self._owner = owner\n\n        @property\n        def beeper_sound(self):\n            return bool(self._owner.enabled)\n\n        @beeper_sound.setter\n        def beeper_sound(self, value):\n            self._owner.set_enabled(bool(value))\n\n    def __init__(self, enabled=True):\n        self.enabled = bool(enabled)\n        self.music = self._MusicCompat(self)\n        self.mixer_ready = False\n        self.channel = None\n        self._cache = {}\n        if self.enabled:\n            self._try_init_mixer()\n\n    def _try_init_mixer(self):\n        try:\n            import pygame\n            if not pygame.mixer.get_init():\n                pygame.mixer.init(frequency=44100, size=-16, channels=1, buffer=512)\n            # BUFFERS.PAS::Crt.Sound / Crt.NoSound is one physical speaker path.\n            self.channel = pygame.mixer.Channel(0)\n            self.mixer_ready = True\n        except Exception:\n            self.mixer_ready = False\n\n    def _audio_path(self, filename):\n        return Path(__file__).resolve().parents[1] / "AUDIO" / filename\n\n    def _load(self, path):\n        key = str(path)\n        if key not in self._cache:\n            import pygame\n            self._cache[key] = pygame.mixer.Sound(key)\n        return self._cache[key]\n\n    def set_enabled(self, enabled):\n        self.enabled = bool(enabled)\n        if not self.enabled:\n            self.no_sound()\n        elif not self.mixer_ready:\n            self._try_init_mixer()\n\n    def no_sound(self):\n        if self.channel is not None:\n            try:\n                self.channel.stop()\n            except Exception:\n                pass\n\n    def sound(self, freq):\n        """BUFFERS.PAS::Beep presentation through a source-derived MP3 sample."""\n        if not freq or not self.enabled:\n            return\n        if not self.mixer_ready:\n            self._try_init_mixer()\n        if not self.mixer_ready or self.channel is None:\n            return\n        freq_i = int(freq)\n        path = self._audio_path(f"BEEP_{freq_i}.mp3")\n        if not path.exists():\n            return\n        try:\n            # Crt.Sound replaces the current PC-speaker tone.\n            self.channel.play(self._load(path), loops=0)\n        except Exception:\n            self.mixer_ready = False\n\n    def beep(self, freq):\n        if self.enabled:\n            self.sound(freq)\n\n    def start(self, name):\n        """Play the complete MP3 produced from MUSIC.PAS."""\n        if not self.enabled:\n            return\n        if not isinstance(name, str) or name not in self.MUSIC_NAMES:\n            return\n        if not self.mixer_ready:\n            self._try_init_mixer()\n        if not self.mixer_ready or self.channel is None:\n            return\n        path = self._audio_path(f"{name}.mp3")\n        if not path.exists():\n            return\n        try:\n            # The MP3 already contains the complete MUSIC.PAS timing.\n            self.channel.play(self._load(path), loops=0)\n        except Exception:\n            self.mixer_ready = False\n\n    def tick(self):\n        # No MUSIC.PAS interpreter is required: tracks are pre-rendered MP3s.\n        return\n\n    def stop(self):\n        self.no_sound()\n'
_BUNDLED_MODULES['block_runtime'] = '# -*- coding: utf-8 -*-\n"""STEP004 faithful state translation of BLOCKS.PAS and TMPOBJ.PAS BreakBlock."""\nW=16\nH=16\nBUMP_HEIGHT=4\nMOVE_DELAY=0\n\nclass BlockRuntime:\n    def __init__(self):\n        self.bumping=False\n        self.bump_x=0; self.bump_y=0\n        self.old_bump_x=0; self.old_bump_y=0\n        self.dy=0; self.delay_counter=0\n        self.block_buffer=None\n        self.backgr_buffer=None\n    def init_blocks(self):\n        # BLOCKS.PAS InitBlocks\n        self.bumping=False\n    def save_bump_backgr(self, get_image):\n        # BLOCKS.PAS SaveBumpBackGr\n        self.backgr_buffer=get_image(self.bump_x,self.bump_y-BUMP_HEIGHT,W,H+BUMP_HEIGHT)\n        self.old_bump_x=self.bump_x; self.old_bump_y=self.bump_y\n    def bump_block(self,x,y,get_image):\n        # BLOCKS.PAS BumpBlock 49-61\n        if self.bumping: return False\n        self.bump_x=x; self.bump_y=y; self.dy=-BUMP_HEIGHT\n        self.block_buffer=get_image(x,y,W,H)\n        self.save_bump_backgr(get_image)\n        self.bumping=True; self.delay_counter=0\n        return True\n    def move_blocks(self):\n        # BLOCKS.PAS MoveBlocks\n        if self.bumping:\n            self.delay_counter += 1\n            if self.delay_counter > MOVE_DELAY and self.dy < BUMP_HEIGHT:\n                self.dy += 1; self.delay_counter=0\n    def draw_blocks_state(self):\n        # Pure coordinate result of BLOCKS.PAS DrawBlocks; renderer remains external.\n        if not self.bumping: return None\n        if self.dy < BUMP_HEIGHT:\n            self.old_bump_x=self.bump_x; self.old_bump_y=self.bump_y\n            y=self.bump_y-BUMP_HEIGHT+abs(self.dy)\n            return (self.bump_x,y,W,H,BUMP_HEIGHT-abs(self.dy))\n        if self.delay_counter >= 4: self.bumping=False\n        return None\n\ndef break_block(world,x,y,remove,new_temp_obj,beep,add_score=None):\n    # TMPOBJ.PAS BreakBlock 290-304\n    world.set(x,y,\' \')\n    px=x*W; py=y*H\n    remove(px,py,W,H,0)\n    x1=px; x2=px+W//2; y1=py; y2=py+H//2\n    new_temp_obj(\'tpBroken\',x1,y1,-2,-6,12,H//2)\n    new_temp_obj(\'tpBroken\',x2,y1, 2,-6,12,H//2)\n    new_temp_obj(\'tpBroken\',x1,y2,-2,-4,12,H//2)\n    new_temp_obj(\'tpBroken\',x2,y2, 2,-4,12,H//2)\n    beep(110)\n'
